package com.elitedarkkaiser.nubialy;
import org.junit.Test;
import static org.junit.Assert.*;
public class QsThemeTest {
 @Test public void boundedConfigurationRoundTripsAndLegacyStaysStock(){var t=SurfaceStyle.QsTheme.STOCK.with(0,0xff102030).with(6,1).with(9,1).withImage("a".repeat(64));var s=SurfaceStyle.STOCK.withQsTheme(t);assertTrue(s.valid());assertEquals(s,SurfaceStyle.decode(s.encode()));assertEquals(t,s.withBatteryStyle(2).qsTheme());assertEquals(t,s.withBatteryControls(1,1).qsTheme());assertEquals(SurfaceStyle.QsTheme.STOCK,SurfaceStyle.decode(SurfaceStyle.STOCK.encode()).qsTheme());}
 @Test public void qsBatteryTextColorIsIndependentAndMigrates(){var stock=SurfaceStyle.QsTheme.STOCK;String[] fields=stock.encode().split(":",-1);for(int count:new int[]{15,21,23,24})assertEquals(stock,SurfaceStyle.QsTheme.decode(String.join(":",java.util.Arrays.copyOf(fields,count))));var t=stock.with(23,0xff123456);assertTrue(t.any());assertTrue(t.valid());assertEquals(t,SurfaceStyle.QsTheme.decode(t.encode()));assertEquals(t,SurfaceStyle.decode(SurfaceStyle.STOCK.withQsTheme(t).encode()).qsTheme());assertEquals(t,SurfaceStyle.QsTheme.merge(stock,t,"header"));assertEquals(stock,SurfaceStyle.QsTheme.merge(stock,t,"colors"));assertEquals(0xff123456,t.withImage("a".repeat(64)).batteryTextColor());assertFalse(t.with(23,0x33123456).valid());}
 @Test public void neonSettingsRoundTripAndStayWithinColorsScope(){var stock=SurfaceStyle.QsTheme.STOCK;var neon=stock.with(24,1).with(25,2).with(26,85);assertTrue(neon.valid());assertTrue(neon.any());assertEquals(neon,SurfaceStyle.QsTheme.decode(neon.encode()));assertEquals(neon,SurfaceStyle.decode(SurfaceStyle.STOCK.withQsTheme(neon).encode()).qsTheme());assertEquals(neon,SurfaceStyle.QsTheme.merge(stock,neon,"colors"));assertEquals(stock,SurfaceStyle.QsTheme.merge(stock,neon,"header"));assertEquals(neon,neon.withImage("a".repeat(64)).withImage(""));assertFalse(neon.with(24,3).valid());assertFalse(neon.with(25,-1).valid());assertFalse(neon.with(26,101).valid());}
 @Test public void arbitraryPathsAlphaAndOutOfBoundsAreRejected(){assertFalse(SurfaceStyle.QsTheme.STOCK.withImage("../../secret").valid());assertFalse(SurfaceStyle.QsTheme.STOCK.with(0,0x10112233).valid());assertFalse(SurfaceStyle.QsTheme.STOCK.with(12,101).valid());assertFalse(SurfaceStyle.QsTheme.STOCK.with(14,9).valid());assertNull(SurfaceStyle.decode(SurfaceStyle.STOCK.encode()+"~bad"));assertNull(SurfaceStyle.decode(SurfaceStyle.STOCK.encode()+"~"+"x".repeat(2000)));}
}
